const extraSources={artemisia_gentileschi:[['Национальная галерея: автопортрет','https://www.nationalgallery.org.uk/paintings/artemisia-gentileschi-self-portrait-as-saint-catherine-of-alexandria'],['Научный каталог: ограничения психологического толкования','https://www.nationalgallery.org.uk/paintings/catalogues/national-gallery-2024/self-portrait-as-saint-catherine-of-alexandria']],salvator_rosa:[['Национальная галерея: Меркурий и дровосек','https://www.nationalgallery.org.uk/paintings/salvator-rosa-landscape-with-mercury-and-the-dishonest-woodsman'],['Национальная галерея: путь художника','https://www.nationalgallery.org.uk/paintings/salvator-rosa-landscape-with-travellers-asking-the-way']],jacob_van_ruisdael:[['Национальная галерея: мельницы и шлюз','https://www.nationalgallery.org.uk/paintings/jacob-van-ruisdael-two-watermills-and-an-open-sluice-at-singraven']],nicolas_poussin:[['Чикаго: расширенное описание','https://www.artic.edu/artworks/5848/landscape-with-saint-john-on-patmos']],johannes_vermeer:[['Метрополитен: художник','https://www.metmuseum.org/essays/johannes-vermeer-1632-1675'],['Метрополитен: свет и композиция','https://www.metmuseum.org/audio-guide/127']]};
